export function getVolumetricDivisor(
  destination?: string,
  country?: string,
  destinationCode?: string,
  explicitDivisor?: number,
  countries: CountryOption[] = [],
): number {
  if (explicitDivisor && explicitDivisor > 0) return explicitDivisor;

  const countryKey = String(country || "").trim().toUpperCase();

  const fromMaster = countries.find((c) => {
    const name = String(c.name || "").trim().toUpperCase();
    const code = String(c.code || "").trim().toUpperCase();

    return (
      name === countryKey ||
      code === countryKey ||
      `${name} (${code})` === countryKey
    );
  });

  if (fromMaster && fromMaster.volumetricDivisor > 0) {
    return fromMaster.volumetricDivisor;
  }

  const text = [destination, country, destinationCode]
    .map((v) => String(v || "").toUpperCase())
    .join(" ");

  if (
    text.includes("AUSTRALIA") ||
    text.includes("AUSTRALIAN") ||
    /\bAUS\b/.test(text) ||
    text.includes("SYDNEY") ||
    text.includes("MELBOURNE") ||
    text.includes("BRISBANE") ||
    text.includes("PERTH") ||
    text.includes("ADELAIDE")
  ) {
    return 4000;
  }

  return DEFAULT_VOLUMETRIC_DIVISOR;
}

function extractList(data: unknown): Record<string, unknown>[] {
  if (Array.isArray(data)) return data as Record<string, unknown>[];
  if (!data || typeof data !== "object") return [];
  const obj = data as Record<string, unknown>;
  for (const key of [
    "items",
    "results",
    "destinations",
    "coloaders",
    "coLoaders",
    "fuelSurcharges",
    "senders",
    "receivers",
    "vendors",
    "currencies",
    "origins",
    "carrierRates",
    "rates",
    "rows",
    "data",
  ]) {
    if (Array.isArray(obj[key])) return obj[key] as Record<string, unknown>[];
  }
  return [];
}

