function computeFreightFromRateClient(
  rate: CarrierRateRow,
  chargeableWeightKg: number,
): number {
  const w = Math.max(0, Number(chargeableWeightKg) || 0);
  if (rate.rateType === "PER_KG") {
    return Math.round((rate.price * w + Number.EPSILON) * 100) / 100;
  }
  return Math.round((rate.price + Number.EPSILON) * 100) / 100;
}

function findFuelVendor(
  vendors: FuelVendorOption[],
  key: string,
): FuelVendorOption | undefined {
  const k = String(key || "").trim();
  if (!k) return undefined;

  return vendors.find((v) => {
    const code = String(v.code || "").trim();
    const name = String(v.name || "").trim();
    const baseName = name.split(" (")[0]?.trim() || name;
    return (
      v.id === k ||
      code === k ||
      name === k ||
      baseName === k ||
      name.startsWith(k) ||
      (code && k.startsWith(code)) ||
      (baseName && k.startsWith(baseName))
    );
  });
}

function calcFuelSurcharge(
  vendor: FuelVendorOption | undefined,
  freight: number,
): number {
  if (!vendor) return 0;
  const f = Math.max(0, Number(freight) || 0);
  if (
    vendor.percentage != null &&
    Number.isFinite(vendor.percentage) &&
    vendor.percentage > 0
  ) {
    return Number(((f * vendor.percentage) / 100).toFixed(2));
  }
  if (
    vendor.amount != null &&
    Number.isFinite(vendor.amount) &&
    vendor.amount > 0
  ) {
    return Number(vendor.amount.toFixed(2));
  }
  return 0;
}

function calcTaxFromVendor(
  vendor: FuelVendorOption | undefined,
  freight: number,
  fuel: number,
  contractCharges: number,
  otherCharges: number,
  discount: number,
): { cgst: number; sgst: number; igst: number } {
  if (!vendor) return { cgst: 0, sgst: 0, igst: 0 };

  const base = Math.max(
    0,
    Number(freight || 0) +
      Number(fuel || 0) +
      Number(contractCharges || 0) +
      Number(otherCharges || 0) -
      Number(discount || 0),
  );

  const igstRate = Number(vendor.igst || 0);
  const cgstRate = Number(vendor.cgst || 0);
  const sgstRate = Number(vendor.sgst || 0);

  return {
    cgst: cgstRate > 0 ? Number(((base * cgstRate) / 100).toFixed(2)) : 0,
    sgst: sgstRate > 0 ? Number(((base * sgstRate) / 100).toFixed(2)) : 0,
    igst: igstRate > 0 ? Number(((base * igstRate) / 100).toFixed(2)) : 0,
  };
}

