function getBaseCurrencyCode(currencies: CurrencyOption[]): string {
  const base = currencies.find((c) => c.isBase);
  return String(base?.code || "INR").toUpperCase();
}

function getRateToBase(
  currencies: CurrencyOption[],
  code: string,
): number {
  const c = currencies.find(
    (x) => x.code === String(code || "").toUpperCase(),
  );
  const rate = Number(c?.rateToBase);
  return rate > 0 ? rate : 1;
}

function fromBaseCurrency(
  amount: number,
  toCode: string,
  currencies: CurrencyOption[],
): number {
  const base = getBaseCurrencyCode(currencies);
  return convertAmount(amount, base, toCode, currencies);
}

function convertAmount(
  amount: number,
  fromCode: string,
  toCode: string,
  currencies: CurrencyOption[],
): number {
  const from = String(fromCode || "INR").toUpperCase();
  const to = String(toCode || "INR").toUpperCase();
  if (from === to) return Number(amount) || 0;

  const fromRate = getRateToBase(currencies, from);
  const toRate = getRateToBase(currencies, to);
  if (toRate <= 0) return Number(amount) || 0;

  return Number(((Number(amount) || 0) * (fromRate / toRate)).toFixed(2));
}

function convertCharges(
  charges: ChargeDetailsData,
  fromCode: string,
  toCode: string,
  currencies: CurrencyOption[],
): ChargeDetailsData {
  const from = String(fromCode || "INR").toUpperCase();
  const to = String(toCode || "INR").toUpperCase();
  if (from === to) return charges;

  const c = (n: number) => convertAmount(n, from, to, currencies);

  return {
    ...charges,
    freight: c(charges.freight),
    fuelSurcharge: c(charges.fuelSurcharge),
    contractCharges: c(charges.contractCharges),
    otherCharges: c(charges.otherCharges),
    surcharge: c(charges.surcharge),
    discount: c(charges.discount),
    cgst: c(charges.cgst),
    sgst: c(charges.sgst),
    igst: c(charges.igst),
    additionalCharges: (charges.additionalCharges || []).map((line) => {
      const amount = c(Number(line.amount) || 0);
      const fuelAmt = c(Number(line.fuelAmt) || 0);
      const taxOnFuel = c(Number(line.taxOnFuel) || 0);
      const igst = c(Number(line.igst) || 0);
      const sgst = c(Number(line.sgst) || 0);
      const cgst = c(Number(line.cgst) || 0);
      return {
        ...line,
        amount,
        fuelAmt,
        taxOnFuel,
        igst,
        sgst,
        cgst,
        total: amount + fuelAmt + taxOnFuel + igst + sgst + cgst,
      };
    }),
  };
}

function chargesGrandTotal(charges: ChargeDetailsData): number {
  const lines = Array.isArray(charges.additionalCharges)
    ? charges.additionalCharges
    : [];
  const extra = lines.reduce((sum, line) => {
    const t = Number(line.total);
    if (Number.isFinite(t)) return sum + t;
    return sum + (Number(line.amount) || 0);
  }, 0);

  const total =
    (Number(charges.freight) || 0) +
    (Number(charges.fuelSurcharge) || 0) +
    (Number(charges.contractCharges) || 0) +
    (Number(charges.otherCharges) || 0) +
    (Number(charges.surcharge) || 0) -
    (Number(charges.discount) || 0) +
    (Number(charges.cgst) || 0) +
    (Number(charges.sgst) || 0) +
    (Number(charges.igst) || 0) +
    extra;

  return Number(total.toFixed(2));
}

function syncFlagChargeLines(
  charges: ChargeDetailsData,
  flags: {
    commercial: boolean;
    oda: boolean;
    medicalCharges: boolean;
  },
  allowCustomFlagAmounts: boolean,
  amounts: { commercial: number; oda: number; medicalCharges: number },
): ChargeDetailsData {
  const existing = Array.isArray(charges.additionalCharges)
    ? [...charges.additionalCharges]
    : [];

  let next = existing.filter(
    (line) => !FLAG_CHARGE_DESCRIPTIONS.has(String(line.description || "")),
  );

  for (const flag of FLAG_CHARGE_LINES) {
    if (!flags[flag.key]) continue;

    const prev = existing.find((l) => l.description === flag.description);
    const adminDefault = Number(amounts[flag.key] || 0);

    const amount =
      allowCustomFlagAmounts && prev && Number(prev.amount) > 0
        ? Number(prev.amount)
        : adminDefault;

    next.push({
      id: prev?.id || crypto.randomUUID(),
      description: flag.description,
      rate: 0,
      amount,
      fuelApply: false,
      fuelAmt: 0,
      taxApply: false,
      taxOnFuel: 0,
      igst: 0,
      sgst: 0,
      cgst: 0,
      total: amount,
    });
  }

  return { ...charges, additionalCharges: next };
}

