//     lockAccountFields = false,
//     isEdit = false,
//   } = options || {};

function mergeInitial(
  initialValue?: Partial<AWBBookingData> | null,
  options?: {
    defaultAccountCode?: string;
    defaultClientName?: string;
    lockAccountFields?: boolean;
    isEdit?: boolean;
  },
): AWBBookingData {
  const {
    defaultAccountCode = "",
    defaultClientName = "",
    lockAccountFields = false,
    isEdit = false,
  } = options || {};

//   const currencyRaw = String(initialValue?.currency || "INR").toUpperCase();
//   const currency: "INR" | "USD" = currencyRaw === "USD" ? "USD" : "INR";
const currency =
    String(initialValue?.currency || "INR").trim().toUpperCase() || "INR";

  let accountCode = "";
  let customerName = "";

  if (lockAccountFields) {
    accountCode =
      initialValue?.accountCode ||
      defaultAccountCode ||
      defaultData.accountCode;
    customerName =
      initialValue?.customerName ||
      defaultClientName ||
      defaultData.customerName;
  } else if (isEdit) {
    accountCode = initialValue?.accountCode || "";
    customerName = initialValue?.customerName || "";
  }

  const mergedCharges = {
    ...defaultCharges,
    ...initialValue?.charges,
    additionalCharges: Array.isArray(initialValue?.charges?.additionalCharges)
      ? initialValue!.charges!.additionalCharges
      : [],
  };

  return {
    ...defaultData,
    ...initialValue,
    accountCode,
    customerName,
    customerId: initialValue?.customerId || "",
    customerCode: initialValue?.customerCode || "",
    currency,
    shipper: { ...defaultShipper, ...initialValue?.shipper },
    consignee: { ...defaultConsignee, ...initialValue?.consignee },
    charges: mergedCharges,
    pieces: Array.isArray(initialValue?.pieces)
      ? initialValue!.pieces!
      : defaultData.pieces,
    items: Array.isArray(initialValue?.items)
      ? initialValue!.items!
      : defaultData.items,
  };
}

