  useEffect(() => {
  let cancelled = false;

  async function loadOrigins() {
    try {
      const headers = await authHeaders();

      const res = await fetch("/api/logistics/origins", {
        method: "GET",
        headers,
        credentials: "include",
        cache: "no-store",
      });

      const json = await res.json();

      if (!res.ok || !json?.success || cancelled) {
        console.error("Failed to load origins:", json);
        return;
      }

      const list = extractList(json.data);

      if (cancelled) return;

      const mapped: OriginOption[] = [];

      for (const row of list) {
        const id = String(row.id || row.originId || "").trim();
        const name = String(row.name || "").trim();
        const code = String(row.code || "")
          .trim()
          .toUpperCase();

        const status = String(row.status || "ACTIVE").toUpperCase();
        const enabled =
          row.enabled === undefined
            ? status !== "INACTIVE"
            : Boolean(row.enabled);

        if (!name || !enabled) continue;

        mapped.push({
          id: id || name,
          name,
          code: code || undefined,
        });
      }

      setOrigins(mapped);
    } catch (error) {
      if (!cancelled) {
        console.error("Failed to load origins:", error);
        setOrigins([]);
      }
    }
  }

  loadOrigins();

  return () => {
    cancelled = true;
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [firebaseUser]);

  // Recalc fuel + tax when freight / extras change
  useEffect(() => {
    setData((prev) => {
      const fuel = calcFuelSurcharge(selectedVendor, prev.charges.freight);
      const tax = calcTaxFromVendor(
        selectedVendor,
        prev.charges.freight,
        fuel,
        prev.charges.contractCharges,
        prev.charges.otherCharges,
        prev.charges.discount,
      );
      if (
        fuel === prev.charges.fuelSurcharge &&
        tax.cgst === prev.charges.cgst &&
        tax.sgst === prev.charges.sgst &&
        tax.igst === prev.charges.igst
      ) {
        return prev;
      }
      return {
        ...prev,
        charges: {
          ...prev.charges,
          fuelSurcharge: fuel,
          cgst: tax.cgst,
          sgst: tax.sgst,
          igst: tax.igst,
        },
      };
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    data.charges.freight,
    data.charges.contractCharges,
    data.charges.otherCharges,
    data.charges.discount,
    selectedVendor,
  ]);

  const selectedCountry = useMemo(
    () =>
      countries.find((c) => {
        const country = String(data.consignee.country || "")
          .trim()
          .toUpperCase();

        return (
          String(c.name || "").trim().toUpperCase() === country ||
          String(c.code || "").trim().toUpperCase() === country ||
          String(c.id || "").trim().toUpperCase() === country
        );
      }),
    [countries, data.consignee.country],
  );

  const volumetricDivisor = useMemo(
    () =>
      getVolumetricDivisor(
        data.destination,
        data.consignee.country,
        data.destinationCode,
        selectedCountry?.volumetricDivisor,
        countries,
      ),
    [
      data.destination,
      data.consignee.country,
      data.destinationCode,
      selectedCountry?.volumetricDivisor,
      countries,
    ],
  );

