        //     Number.isFinite(selectedVendor.percentage) &&
        //     selectedVendor.percentage > 0
        //   ) {
        //     fuel = calcFuelSurcharge(selectedVendor, freight);
        //   } else if (
        //     selectedVendor?.amount != null &&
        //     Number.isFinite(selectedVendor.amount) &&
        //     selectedVendor.amount > 0
        //   ) {
        //     fuel = fromBaseCurrency(
        //       Number(selectedVendor.amount),
        //       cur,
        //       currencies,
        //     );
        //   }

        //   const tax = calcTaxFromVendor(
        //     selectedVendor,
        //     freight,
        //     fuel,
        //     prev.charges.contractCharges,
        //     prev.charges.otherCharges,
        //     prev.charges.discount,
        //   );

        //   return {
        //     ...prev,
        //     charges: {
        //       ...prev.charges,
        //       freight,
        //       fuelSurcharge: fuel,
        //       cgst: tax.cgst,
        //       sgst: tax.sgst,
        //       igst: tax.igst,
        //     },
        //   };
        // });

    const freightBase = computeFreightFromRateClient(matched, weight);
    if (!Number.isFinite(freightBase) || freightBase < 0) return;

    setData((prev) => {
      const cur = String(prev.currency || "INR").toUpperCase();
      // Rates are in BASE currency → show in form currency
      const freight = fromBaseCurrency(freightBase, cur, currencies);

      const prevFreight = Number(prev.charges.freight) || 0;
      if (Math.abs(prevFreight - freight) < 0.01) return prev;

      const fuelVendor =
        findFuelVendor(fuelVendors, prev.vendor) ||
        fuelVendors.find(
          (f) =>
            cleanVendorKey(f.name) === cleanVendorKey(prev.vendor) ||
            cleanVendorKey(f.code) === cleanVendorKey(prev.vendor),
        );

      let fuel = 0;
      if (
        fuelVendor?.percentage != null &&
        Number.isFinite(fuelVendor.percentage) &&
        fuelVendor.percentage > 0
      ) {
        fuel = calcFuelSurcharge(fuelVendor, freight);
      } else if (
        fuelVendor?.amount != null &&
        Number.isFinite(fuelVendor.amount) &&
        fuelVendor.amount > 0
      ) {
        fuel = fromBaseCurrency(Number(fuelVendor.amount), cur, currencies);
      }

      const tax = calcTaxFromVendor(
        fuelVendor,
        freight,
        fuel,
        Number(prev.charges.contractCharges) || 0,
        Number(prev.charges.otherCharges) || 0,
        Number(prev.charges.discount) || 0,
      );

      return {
        ...prev,
        charges: {
          ...prev.charges,
          freight,
          fuelSurcharge: fuel,
          cgst: tax.cgst,
          sgst: tax.sgst,
          igst: tax.igst,
        },
      };
    });

