function handleSenderSelect(id: string) {
    setSelectedSenderId(id);

    // Cleared dropdown → blank manual entry (not previous person)
    if (!id) {
      setData((prev) => ({
        ...prev,
        shipper: {
          ...defaultShipper,
          // keep origin if you want it independent of sender; otherwise remove these two lines
          origin: prev.shipper.origin || prev.origin || "",
          originCode: prev.shipper.originCode || prev.originCode || "",
          senderId: "",
        },
      }));
      return;
    }

    const s = senders.find((x) => x.id === id || x.senderId === id);
    if (!s) return;

    setData((prev) => ({
      ...prev,
      shipper: {
        ...prev.shipper,
        ...mapSenderToShipper(s),
        senderId: s.senderId || s.id,
      },
    }));
  }

   async function ensureSenderSaved(
    shipper: ShipperFormData,
  ): Promise<{ senderId: string; shipper: ShipperFormData }> {
    const existingId = String(
      selectedSenderId || shipper.senderId || "",
    ).trim();

    // Already from master dropdown (or previously saved)
    if (existingId) {
      return {
        senderId: existingId,
        shipper: { ...shipper, senderId: existingId },
      };
    }

    const headers = await authHeaders();
    const res = await fetch("/api/logistics/senders", {
      method: "POST",
      headers: {
        ...headers,
        "Content-Type": "application/json",
      },
      credentials: "include",
      body: JSON.stringify({
        companyName: shipper.company || shipper.name || "",
        contactName: shipper.contactName || shipper.name || "",
        name: shipper.contactName || shipper.name || "",
        phone: shipper.phone || "",
        mobile: shipper.mobile || "",
        email: shipper.email || "",
        addressLine1: shipper.addressLine1 || "",
        addressLine2: shipper.addressLine2 || "",
        address: shipper.addressLine1 || "",
        city: shipper.city || "",
        state: shipper.state || "",
        postalCode: shipper.pincode || "",
        country: shipper.country || "",
        gstin: shipper.gstin || "",
        iecNo: shipper.iecNo || "",
        documentType: shipper.documentType || "",
        documentNo: shipper.documentNo || "",
        documentUrl: shipper.documentUrl || "",
        status: "ACTIVE",
      }),
    });

    const json = await res.json();
    if (!res.ok || !json?.success) {
      const msg =
        typeof json?.error === "string"
          ? json.error
          : json?.error?.message || "Failed to save sender to masters.";
      throw new Error(msg);
    }

    const created = (json.data || {}) as Record<string, unknown>;
    const senderId = String(
      created.senderId || created.id || "",
    ).trim();
    if (!senderId) {
      throw new Error("Sender was created but no id was returned.");
    }

    // Refresh local dropdown list
    setSenders((prev) => {
      if (prev.some((s) => s.id === senderId || s.senderId === senderId)) {
        return prev;
      }
      return [
        ...prev,
        {
          id: senderId,
          senderId,
          name: String(created.name || shipper.contactName || shipper.name || ""),
          companyName: String(
            created.companyName || shipper.company || "",
          ),
          phone: String(created.phone || shipper.phone || ""),
          email: shipper.email,
          address: shipper.addressLine1,
          city: shipper.city,
          state: shipper.state,
          postalCode: shipper.pincode,
          gstin: shipper.gstin,
          country: shipper.country,
          mobile: shipper.mobile,
          contactName: shipper.contactName,
          addressLine2: shipper.addressLine2,
          iecNo: shipper.iecNo,
          documentType: shipper.documentType,
          documentNo: shipper.documentNo,
          documentUrl: shipper.documentUrl,
        },
      ];
    });
    setSelectedSenderId(senderId);

    return {
      senderId,
      shipper: { ...shipper, senderId },
    };
  }

  async function ensureReceiverSaved(
    consignee: ConsigneeFormData,
  ): Promise<{ receiverId: string; consignee: ConsigneeFormData }> {
    const existingId = String(
      selectedReceiverId || consignee.receiverId || "",
    ).trim();

    if (existingId) {
      return {
        receiverId: existingId,
        consignee: { ...consignee, receiverId: existingId },
      };
    }

    const headers = await authHeaders();
    const res = await fetch("/api/logistics/receivers", {
      method: "POST",
      headers: {
        ...headers,
        "Content-Type": "application/json",
      },
      credentials: "include",
      body: JSON.stringify({
        companyName: consignee.company || consignee.name || "",
        contactName: consignee.contactName || consignee.name || "",
        name: consignee.contactName || consignee.name || "",
        phone: consignee.phone || consignee.mobile || "",
        mobile: consignee.mobile || consignee.phone || "",
        email: consignee.email || "",
        addressLine1: consignee.addressLine1 || "",
        addressLine2: consignee.addressLine2 || "",
        address: consignee.addressLine1 || "",
        city: consignee.city || "",
        state: consignee.state || "",
        postalCode: consignee.pincode || "",
        country: consignee.country || "",
        gstin: consignee.gstin || "",
        iecNo: consignee.iecNo || "",
        documentType: consignee.documentType || "",
        documentNo: consignee.documentNo || "",
        documentUrl: consignee.documentUrl || "",
        status: "ACTIVE",
      }),
    });

    const json = await res.json();
    if (!res.ok || !json?.success) {
      const msg =
        typeof json?.error === "string"
          ? json.error
          : json?.error?.message || "Failed to save receiver to masters.";
      throw new Error(msg);
    }

    const created = (json.data || {}) as Record<string, unknown>;
    const receiverId = String(
      created.receiverId || created.id || "",
    ).trim();
    if (!receiverId) {
      throw new Error("Receiver was created but no id was returned.");
    }

    setReceivers((prev) => {
      if (
        prev.some((r) => r.id === receiverId || r.receiverId === receiverId)
      ) {
        return prev;
      }
      return [
        ...prev,
        {
          id: receiverId,
          receiverId,
          name: String(
            created.name || consignee.contactName || consignee.name || "",
          ),
          companyName: String(
            created.companyName || consignee.company || "",
          ),
          phone: consignee.phone,
          mobile: consignee.mobile,
          email: consignee.email,
          address: consignee.addressLine1,
          addressLine2: consignee.addressLine2,
          city: consignee.city,
          state: consignee.state,
          postalCode: consignee.pincode,
          country: consignee.country,
          contactName: consignee.contactName,
          gstin: consignee.gstin,
          iecNo: consignee.iecNo,
          documentType: consignee.documentType,
          documentNo: consignee.documentNo,
          documentUrl: consignee.documentUrl,
        },
      ];
    });
    setSelectedReceiverId(receiverId);

    return {
      receiverId,
      consignee: { ...consignee, receiverId },
    };
  }

