function handleReceiverSelect(id: string) {
    setSelectedReceiverId(id);

    // Cleared dropdown → blank manual entry
    if (!id) {
      setData((prev) => ({
        ...prev,
        consignee: {
          ...defaultConsignee,
          receiverId: "",
        },
      }));
      return;
    }

    const r = receivers.find((x) => x.id === id || x.receiverId === id);
    if (!r) return;

    setData((prev) => ({
      ...prev,
      consignee: {
        ...prev.consignee,
        ...mapReceiverToConsignee(r),
        receiverId: r.receiverId || r.id,
      },
    }));
  }

