function handleDestinationSelect(name: string) {
  if (!name) {
    setData((prev) => ({
      ...prev,
      destination: "",
      destinationCode: "",
    }));
    return;
  }

  const d = destinations.find(
    (x) => x.name === name || x.code === name || x.id === name,
  );

  setData((prev) => ({
    ...prev,
    destination: d?.name || name,
    destinationCode: d?.code || "",
  }));
}

  function handleCountryChange(country: string) {
    const selectedCountry = countries.find(
      (c) =>
        c.name === country ||
        c.code === country ||
        c.id === country,
    );

    const nextDivisor =
      selectedCountry?.volumetricDivisor || DEFAULT_VOLUMETRIC_DIVISOR;

    setData((prev) => ({
      ...prev,
      consignee: { ...prev.consignee, country },
      pieces: Array.isArray(prev.pieces)
        ? prev.pieces.map((piece) => ({
            ...piece,
            division: nextDivisor,
          }))
        : prev.pieces,
    }));
  }

