  function handleCoLoaderSelect(code: string) {
    const selected = String(code || "").trim();

    if (!selected) {
      setData((prev) => ({
        ...prev,
        accountCode: "",
        customerName: "",
        customerId: "",
      }));
      return;
    }

    const c = coloaders.find((x) => x.code === selected);

    setData((prev) => ({
      ...prev,
      accountCode: selected,
      customerName: c?.name || "",
      customerId: c?.id || "",
    }));
  }

