  function setServiceFlag(
    key: "commercial" | "oda" | "medicalCharges",
    checked: boolean,
  ) {
    setData((prev) => {
      const flags = {
        commercial: key === "commercial" ? checked : prev.commercial,
        oda: key === "oda" ? checked : prev.oda,
        medicalCharges:
          key === "medicalCharges" ? checked : prev.medicalCharges,
      };

      // flagAmounts are configured in base currency (INR) → convert to form currency
      const cur = String(prev.currency || "INR").toUpperCase();
      const amountsInCurrency = {
        commercial: fromBaseCurrency(
          Number(flagAmounts.commercial) || 0,
          cur,
          currencies,
        ),
        oda: fromBaseCurrency(Number(flagAmounts.oda) || 0, cur, currencies),
        medicalCharges: fromBaseCurrency(
          Number(flagAmounts.medicalCharges) || 0,
          cur,
          currencies,
        ),
      };

      return {
        ...prev,
        ...flags,
        charges: syncFlagChargeLines(
          prev.charges,
          flags,
          canManageCharges,
          amountsInCurrency,
        ),
      };
    });
  }

  function handleReset() {
    setData(
      mergeInitial(null, {
        defaultAccountCode,
        defaultClientName,
        lockAccountFields,
        isEdit: false,
      }),
    );
    setSelectedSenderId("");
    setSelectedReceiverId("");
    setError("");
  }

